// ---------- PRECOMP ----------
// AE creates precomps at the parent comp's full duration. Convert the nested
// comp to the selected layers' actual visible range while keeping the new
// precomp layer at the same time in the parent timeline.
function compxTrimPrecompToLayerRange(parentComp, nestedComp, rangeStart, rangeEnd) {
  if (!parentComp || !nestedComp) return;
  var frame = parentComp.frameDuration || (1 / 30);
  rangeStart = Math.max(0, Math.min(parentComp.duration, Number(rangeStart) || 0));
  rangeEnd = Math.max(rangeStart + frame, Math.min(parentComp.duration, Number(rangeEnd) || parentComp.duration));
  var span = Math.max(frame, rangeEnd - rangeStart);

  // Move the selected content so its first visible frame becomes time zero
  // inside the newly created precomp.
  for (var li = 1; li <= nestedComp.numLayers; li++) {
    try { nestedComp.layer(li).startTime -= rangeStart; }
    catch (shiftError) { compxAuditFallback("HOST_AE_PRECOMP_TRIM_SHIFT_001", shiftError); }
  }
  nestedComp.duration = span;
  try { nestedComp.workAreaStart = 0; nestedComp.workAreaDuration = span; }
  catch (workAreaError) { compxAuditFallback("HOST_AE_PRECOMP_TRIM_WORKAREA_001", workAreaError); }

  // Locate the replacement layer created by precompose() and restore the
  // selected range in parent-comp time.
  for (var pi = 1; pi <= parentComp.numLayers; pi++) {
    var replacement = parentComp.layer(pi);
    if (replacement.source !== nestedComp) continue;
    replacement.startTime = rangeStart;
    replacement.inPoint = rangeStart;
    replacement.outPoint = rangeEnd;
    break;
  }
}

function ae_precompose(moveAllAttributes) {
  try {
    var comp = getActiveComp();
    if (!comp) return toolResult(false, "No active composition.");
    var layers = getSelectedLayers(comp);
    if (layers.length === 0) return toolResult(false, "No layers selected.");

    var indices = [];
    var rangeStart = layers[0].inPoint;
    var rangeEnd = layers[0].outPoint;
    for (var i = 0; i < layers.length; i++) {
      indices.push(layers[i].index);
      if (layers[i].inPoint < rangeStart) rangeStart = layers[i].inPoint;
      if (layers[i].outPoint > rangeEnd) rangeEnd = layers[i].outPoint;
    }

    app.beginUndoGroup("Precompose");
    var name = layers.length === 1 ? (layers[0].name + " Precomp") : (comp.name + " Precomp");
    var nestedComp = comp.layers.precompose(indices, name, !!moveAllAttributes);
    if (!!moveAllAttributes) compxTrimPrecompToLayerRange(comp, nestedComp, rangeStart, rangeEnd);
    app.endUndoGroup();
    return toolResult(true, "Precomposed: \"" + name + "\".");
  } catch (e) {
    try { app.endUndoGroup(); } catch (e2) { compxAuditFallback("HOST_AE_PRECOMPOSE_001", e2); }
    return toolResult(false, String(e));
  }
}

// PRECOMP SEP — precomposes each selected layer into its own individual
// comp (as opposed to ae_precompose, which bundles the whole selection
// into a single comp).
function ae_precomposeSeparate() {
  try {
    var comp = getActiveComp();
    if (!comp) return toolResult(false, "No active composition.");
    var layers = getSelectedLayers(comp);
    if (layers.length === 0) return toolResult(false, "No layers selected.");

    // FIX: sort HIGH-to-LOW so each precompose call does not shift the
    // indices of layers still waiting to be processed.
    layers.sort(function (a, b) { return b.index - a.index; });
    var toProcess = [];
    for (var i = 0; i < layers.length; i++) {
      toProcess.push({ idx: layers[i].index, nm: layers[i].name, inPt: layers[i].inPoint, outPt: layers[i].outPoint });
    }

    app.beginUndoGroup("Precompose Separately");
    for (var i = 0; i < toProcess.length; i++) {
      var separateComp = comp.layers.precompose([toProcess[i].idx], toProcess[i].nm + " Precomp", true);
      compxTrimPrecompToLayerRange(comp, separateComp, toProcess[i].inPt, toProcess[i].outPt);
    }
    app.endUndoGroup();
    return toolResult(true, layers.length + " layer(s) precomposed separately.");
  } catch (e) {
    try { app.endUndoGroup(); } catch (e2) { compxAuditFallback("HOST_AE_PRECOMPOSESEPARATE_001", e2); }
    return toolResult(false, String(e));
  }
}

// UNPRECOMP — the inverse of precompose: pulls the layers out of a selected
