    try { wasLocked = layer.locked; layer.locked = false; } catch (lockError) { compxAuditFallback("HOST_AE_UNPRECOMPOSE_OFFSET_LOCK_001", lockError); }
    var tr = layer.property("ADBE Transform Group");
    var pos = tr ? tr.property("ADBE Position") : null;
