function compxMenuCommandId(names, fallbackId) {
  var n, id;
  for (n = 0; n < names.length; n++) {
    try {
      id = app.findMenuCommandId(names[n]);
      if (id) return id;
    } catch (e) { compxAuditFallback("HOST_AE_UNPRECOMPOSE_MENU_001", e); }
  }
  return fallbackId || 0;
}

