    try { trimC.property("ADBE Vector Trim End").setValue(25); } catch (e) { compxAuditFallback("HOST_AE_APPLYSHAPEPRESET_010", e); }
    try { trimC.property("ADBE Vector Trim Offset").expression = "time * " + (360 / ae_shapeLoopDuration(comp, options)) + ";"; } catch (e) { compxAuditFallback("HOST_AE_APPLYSHAPEPRESET_011", e); }
