  try { eP.setValue(100); } catch (e) { compxAuditFallback("HOST_AE_CTRLTRIM_BASELINE_002", e); }
  try { oP.setValue(0); } catch (e) { compxAuditFallback("HOST_AE_CTRLTRIM_BASELINE_003", e); }
