    var a = prop.numKeys - 1;
    var b = prop.numKeys;
    var startValue = prop.keyValue(a);
    var nextValue = prop.keyValue(b);
    var dx = nextValue[0] - startValue[0];
    var dy = nextValue[1] - startValue[1];
