    for (var i = 0; i < dimension; i++) ease.push(new KeyframeEase(0, 72));
    prop.setInterpolationTypeAtKey(prop.nearestKeyIndex(t0), KeyframeInterpolationType.BEZIER, KeyframeInterpolationType.BEZIER);
    prop.setInterpolationTypeAtKey(prop.nearestKeyIndex(t1), KeyframeInterpolationType.BEZIER, KeyframeInterpolationType.BEZIER);
    prop.setTemporalEaseAtKey(prop.nearestKeyIndex(t0), ease, ease);
