  if (!target) { target = comp.layers.addNull(); target.name = "CompX Orbit Target"; target.comment = "COMPX_CAMERA_TARGET"; target.threeDLayer = true; target.property("ADBE Transform Group").property("ADBE Position").setValue([comp.width/2,comp.height/2,0]); }
  if (pathMotion) { pathMotion.comment = "COMPX_CAMERA_PATH_MOTION"; pathMotion.threeDLayer = true; if (pathMotion.parent !== target) pathMotion.parent = target; }
  var rigParent = pathMotion || target;
