  try { var poi = camera.property("ADBE Transform Group").property("ADBE Point of Interest"); if (poi) poi.expression = '// COMPX_CAMERA_TARGET_FOCUS\nthisComp.layer("CompX Orbit Target").toWorld([0,0,0]);'; } catch (poiError) { compxAuditFallback("HOST_COMPXCAMERA_HIERARCHY_POI_001",poiError); }
  return {target:target,rig:rig,shake:shake,camera:camera,pathMotion:pathMotion};
