    var t0=comp.time,header='// COMPX_ISOLATED_CAMERA_SHAKE\na=thisComp.layer("CompX Camera Rig").effect("Shake Amount")(1);\nf=thisComp.layer("CompX Camera Rig").effect("Shake Frequency")(1);',transform=h.shake.property("ADBE Transform Group");
    transform.property("ADBE Position").expression=header+"\n"+preset.pos.replace(/T0/g,String(t0));
    transform.property("ADBE Orientation").expression=header+"\n"+preset.ori.replace(/T0/g,String(t0));
