  if(enabled)focus.expression='// COMPX_DYNAMIC_CAMERA_FOCUS\nt=thisComp.layer("CompX Orbit Target");length(thisLayer.toWorld([0,0,0]),t.toWorld([0,0,0]));';
  else if(String(focus.expression).indexOf("COMPX_DYNAMIC_CAMERA_FOCUS")>=0)focus.expression="";
