  for(var i=0;i<lines.length;i++)if(lines[i].indexOf(key)===0){var raw=lines[i].substring(key.length).split(","),values=[];for(var j=0;j<raw.length;j++)values.push(Number(raw[j]));return values.length>=18?values:null;}
  return null;
