function compxCameraSelectedMaskPath(comp) {
  var selected=getSelectedLayers(comp);for(var i=0;i<selected.length;i++){var props=selected[i].selectedProperties||[];for(var j=0;j<props.length;j++){if(props[j].matchName==="ADBE Mask Shape")return {layer:selected[i],property:props[j]};if(props[j].matchName==="ADBE Vector Shape")return {shape:true};}}return null;
}

function compxMeshPickPath(comp) {
  var selected = getSelectedLayers(comp), i, j, props, prop;
  for (i = 0; i < selected.length; i++) {
    props = selected[i].selectedProperties || [];
    for (j = 0; j < props.length; j++) {
      prop = props[j];
      if (prop.matchName === "ADBE Mask Shape") return { layer: selected[i], property: prop, kind: "mask" };
      if (prop.matchName === "ADBE Vector Shape") return { layer: selected[i], property: prop, kind: "shape" };
    }
  }
  return null;
}

function ae_meshExtrudeFromPath(depth) {
  var undoOpen = false;
  try {
    if (!isAfterEffects()) return toolResult(false, "Path extrude is available in After Effects only.");
    var comp = getActiveComp();
    if (!comp) return toolResult(false, "Open a composition first.");
    var picked = compxMeshPickPath(comp);
    if (!picked) return toolResult(false, "Select a Mask Path or Shape Path in the timeline, then try again.");
    var shapeVal = picked.property.value;
    if (!shapeVal || !shapeVal.vertices || shapeVal.vertices.length < 2) {
      return toolResult(false, "The path needs at least 2 points.");
    }
    var amount = Number(depth);
    if (!(amount > 0)) amount = 80;
    amount = Math.max(4, Math.min(800, amount));
    app.beginUndoGroup("Extrude CompX Path");
    undoOpen = true;
    compxMeshEnableRenderer(comp);
    var srcLayer = picked.layer;
    var layer = comp.layers.addShape();
    layer.name = (srcLayer.name || "Path") + " 3D";
    layer.comment = "COMPX_MESH|path";
    try {
      layer.moveBefore(srcLayer);
    } catch (orderError) { compxAuditFallback("HOST_MESH_PATH_ORDER_001", orderError); }
    try {
      layer.property("ADBE Transform Group").property("ADBE Position").setValue(
        srcLayer.property("ADBE Transform Group").property("ADBE Position").value
      );
    } catch (posError) { compxAuditFallback("HOST_MESH_PATH_POS_001", posError); }
    var contents = layer.property("ADBE Root Vectors Group");
    var group = contents.addProperty("ADBE Vector Group");
    group.name = "Path";
    var groupContents = group.property("ADBE Vectors Group");
    var pathShape = groupContents.addProperty("ADBE Vector Shape - Group").property("ADBE Vector Shape");
    pathShape.setValue(shapeVal);
    var fill = groupContents.addProperty("ADBE Vector Graphic - Fill");
    fill.property("ADBE Vector Fill Color").setValue([0.235, 1, 0.373]);
    try { layer.threeDLayer = true; } catch (threeDError) { compxAuditFallback("HOST_MESH_PATH_3D_001", threeDError); }
    var extruded = compxMapSetExtrusion(layer, amount);
    app.endUndoGroup();
    undoOpen = false;
    if (!extruded) {
      return toolResult(true, "Path layer created in 3D. Switch the comp renderer to Advanced 3D or Cinema 4D to see extrusion.");
    }
    return toolResult(true, "Path extruded to 3D (" + amount + " px).");
  } catch (error) {
    if (undoOpen) try { app.endUndoGroup(); } catch (endError) { compxAuditFallback("HOST_MESH_PATH_END_001", endError); }
    return toolResult(false, "Could not extrude the path: " + String(error));
  }
}

function ae_meshPathToNulls() {
  var undoOpen = false;
  try {
    if (!isAfterEffects()) return toolResult(false, "Path nulls are available in After Effects only.");
    var comp = getActiveComp();
    if (!comp) return toolResult(false, "Open a composition first.");
    var picked = compxMeshPickPath(comp);
    if (!picked) return toolResult(false, "Select a Mask Path or Shape Path in the timeline, then try again.");
    var shapeVal = picked.property.value;
    var vertices = shapeVal && shapeVal.vertices;
    if (!vertices || vertices.length < 2) return toolResult(false, "The path needs at least 2 points.");
    app.beginUndoGroup("CompX Path Nulls");
    undoOpen = true;
    var srcLayer = picked.layer;
    try { srcLayer.threeDLayer = true; } catch (threeDError) { compxAuditFallback("HOST_MESH_PATH_NULLS_3D_001", threeDError); }
    var parent = comp.layers.addNull();
    parent.name = (srcLayer.name || "Path") + " 3D Path";
    parent.comment = "COMPX_MESH_PATH_NULL|root";
    parent.threeDLayer = true;
    parent.label = 11;
    try { parent.moveBefore(srcLayer); } catch (orderError) { compxAuditFallback("HOST_MESH_PATH_NULLS_ORDER_001", orderError); }
    try {
      parent.property("ADBE Transform Group").property("ADBE Position").setValue(
        srcLayer.property("ADBE Transform Group").property("ADBE Position").value
      );
    } catch (posError) { compxAuditFallback("HOST_MESH_PATH_NULLS_POS_001", posError); }
    var count = Math.min(vertices.length, 48);
    var i, point, world, child;
    for (i = 0; i < count; i++) {
      point = vertices[i];
      child = comp.layers.addNull();
      child.name = "P" + (i + 1);
      child.comment = "COMPX_MESH_PATH_NULL";
      child.threeDLayer = true;
      child.label = 11;
      child.parent = parent;
      try { child.moveBefore(srcLayer); } catch (childOrderError) { compxAuditFallback("HOST_MESH_PATH_NULLS_CHILD_001", childOrderError); }
      try {
        world = srcLayer.toWorld([Number(point[0]) || 0, Number(point[1]) || 0, 0]);
        child.property("ADBE Transform Group").property("ADBE Position").setValue(world);
      } catch (worldError) {
        try { child.property("ADBE Transform Group").property("ADBE Position").setValue([Number(point[0]) || 0, Number(point[1]) || 0, 0]); }
        catch (localError) { compxAuditFallback("HOST_MESH_PATH_NULLS_LOCAL_001", localError); }
      }
    }
    app.endUndoGroup();
    undoOpen = false;
    return toolResult(true, count + " path point(s) converted to 3D nulls.");
  } catch (error) {
    if (undoOpen) try { app.endUndoGroup(); } catch (endError) { compxAuditFallback("HOST_MESH_PATH_NULLS_END_001", endError); }
    return toolResult(false, "Could not build path nulls: " + String(error));
  }
}

function ae_duplicate3DModel() {
  try {
    if (!isAfterEffects()) return toolResult(false, "Duplicate is available in After Effects only.");
    var comp = getActiveComp();
    if (!comp) return toolResult(false, "Open a composition first.");
    var layers = getSelectedLayers(comp);
    if (!layers.length) return toolResult(false, "Select a 3D layer to duplicate.");
    app.beginUndoGroup("Duplicate CompX 3D");
    var count = 0;
    var i, layer, copy, isCam, isLight, pos;
    for (i = 0; i < layers.length; i++) {
      layer = layers[i];
      isCam = false;
      isLight = false;
      try { isCam = layer instanceof CameraLayer; } catch (camError) { isCam = false; }
      try { isLight = layer instanceof LightLayer; } catch (lightError) { isLight = false; }
      if (isCam || isLight) continue;
      copy = layer.duplicate();
      try { copy.threeDLayer = true; } catch (threeDError) { compxAuditFallback("HOST_MESH_DUP_3D_001", threeDError); }
      try {
        pos = copy.property("ADBE Transform Group").property("ADBE Position").value;
        copy.property("ADBE Transform Group").property("ADBE Position").setValue([pos[0] + 40, pos[1], (pos.length > 2 ? pos[2] : 0) - 20]);
      } catch (posError) { compxAuditFallback("HOST_MESH_DUP_POS_001", posError); }
      count++;
    }
    app.endUndoGroup();
    if (!count) return toolResult(false, "Select a visual 3D layer — cameras and lights are skipped.");
    return toolResult(true, "Duplicated " + count + " layer" + (count === 1 ? "" : "s") + ".");
  } catch (error) {
    try { app.endUndoGroup(); } catch (endError) { compxAuditFallback("HOST_MESH_DUP_END_001", endError); }
    return toolResult(false, "Could not duplicate the layer: " + String(error));
  }
}

