// ================================================================
// COMPX: Keylight background removal, shake and expression presets
// ================================================================
function ae_bgRemoveSelectionInfo() {
  try {
    var comp = getActiveComp();
    if (!comp) return toolResult(false, "Open a composition first.");
    var layers = getSelectedLayers(comp);
    if (layers.length !== 1) return toolResult(false, "Select exactly one still-image layer.");
    var layer = layers[0];
    var source = layer.source;
    if (!source || !(source instanceof FootageItem) || !source.file || !source.mainSource || source.mainSource.isStill !== true) {
      return toolResult(false, "Select a PNG, JPG, JPEG or WebP still-image layer. Video and precomps are not supported.");
    }
    var sourcePath = source.file.fsName;
    var extensionMatch = String(sourcePath || "").toLowerCase().match(/\.([a-z0-9]+)$/);
    var extension = extensionMatch ? extensionMatch[1] : "";
    if (extension !== "png" && extension !== "jpg" && extension !== "jpeg" && extension !== "webp") {
      return toolResult(false, "This version supports PNG, JPG, JPEG and WebP still images only.");
    }
    return '{"success":true,"path":"' + escapeJson(sourcePath) + '","name":"' + escapeJson(source.name) + '","layerName":"' + escapeJson(layer.name) + '","compName":"' + escapeJson(comp.name) + '","compId":' + Number(comp.id) + ',"layerId":' + Number(layer.id) + ',"width":' + Number(source.width || 0) + ',"height":' + Number(source.height || 0) + '}';
  } catch (error) {
    return toolResult(false, "Could not read the selected still image: " + error.toString());
  }
}

function ae_bgRemoveImport(outputPath, token, disableOriginal, sourceCompId, sourceLayerId) {
  var undoOpen = false;
  try {
    var comp = null;
    for (var itemIndex = 1; itemIndex <= app.project.numItems; itemIndex++) {
      var projectItem = app.project.item(itemIndex);
      if (projectItem instanceof CompItem && projectItem.id === Number(sourceCompId)) { comp = projectItem; break; }
    }
    if (!comp) return toolResult(false, "The source composition could not be found. It may have been deleted while processing.");
    var original = null;
    for (var layerIndex = 1; layerIndex <= comp.numLayers; layerIndex++) {
      if (comp.layer(layerIndex).id === Number(sourceLayerId)) { original = comp.layer(layerIndex); break; }
    }
    if (!original) return toolResult(false, "The source still-image layer could not be found. It may have been deleted while processing.");
    var source = original.source;
    if (!source || !(source instanceof FootageItem) || !source.mainSource || source.mainSource.isStill !== true) return toolResult(false, "The selected source is no longer a still-image layer.");
    var outputFile = new File(String(outputPath || ""));
    if (!outputFile.exists) return toolResult(false, "The transparent PNG output file was not found.");
    var importOptions = new ImportOptions(outputFile);
    if (!importOptions.canImportAs(ImportAsType.FOOTAGE)) return toolResult(false, "After Effects cannot import the generated PNG.");

    app.beginUndoGroup("CompX AI Remove Background"); undoOpen = true;
    importOptions.importAs = ImportAsType.FOOTAGE;
    var imported = app.project.importFile(importOptions);
    imported.name = source.name.replace(/\.[^.]+$/, "") + " - No BG.png";
    imported.parentFolder = source.parentFolder;
    var originalWasEnabled = original.enabled;
    var result = original.duplicate();
    result.replaceSource(imported, true);
    result.name = original.name + " - AI Cutout";
    result.comment = "COMPX_AI_BG_REMOVED|1|TOKEN=" + String(token || "") + "|SOURCE_ID=" + String(original.id) + "|ORIGINAL_ENABLED=" + (originalWasEnabled ? "1" : "0") + "|FOOTAGE_ID=" + String(imported.id);
    if (disableOriginal !== false) original.enabled = false;
    original.selected = false;
    result.selected = true;
    app.endUndoGroup(); undoOpen = false;
    return toolResult(true, "Background removed and transparent PNG imported. Original layer " + (disableOriginal !== false ? "is preserved as a disabled backup." : "remains visible."));
  } catch (error) {
    if (undoOpen) try { app.endUndoGroup(); } catch (undoError) { compxAuditFallback("HOST_BG_IMPORT_UNDO_001", undoError); }
    return toolResult(false, "Could not import the background-removed image: " + error.toString());
  }
}

function ae_bgRemoveImportDropped(outputPath, sourcePath, token, disableOriginal) {
  var undoOpen = false;
  try {
    var comp = getActiveComp();
    if (!comp) return toolResult(false, "Open a composition first.");
    var outputFile = new File(String(outputPath || ""));
    if (!outputFile.exists) return toolResult(false, "The transparent PNG output file was not found.");
    var sourceFile = new File(String(sourcePath || ""));
    if (!sourceFile.exists) return toolResult(false, "The dropped source image was not found.");
    var sourceOptions = new ImportOptions(sourceFile);
    if (!sourceOptions.canImportAs(ImportAsType.FOOTAGE)) return toolResult(false, "After Effects cannot import the dropped source image.");
    var outputOptions = new ImportOptions(outputFile);
    if (!outputOptions.canImportAs(ImportAsType.FOOTAGE)) return toolResult(false, "After Effects cannot import the generated PNG.");

    app.beginUndoGroup("CompX AI Remove Background"); undoOpen = true;
    sourceOptions.importAs = ImportAsType.FOOTAGE;
    var sourceFootage = app.project.importFile(sourceOptions);
    var original = comp.layers.add(sourceFootage);
    original.name = sourceFootage.name;
    outputOptions.importAs = ImportAsType.FOOTAGE;
    var imported = app.project.importFile(outputOptions);
    imported.name = sourceFootage.name.replace(/\.[^.]+$/, "") + " - No BG.png";
    imported.parentFolder = sourceFootage.parentFolder;
    var originalWasEnabled = original.enabled;
    var result = original.duplicate();
    result.replaceSource(imported, true);
    result.name = original.name + " - AI Cutout";
    result.comment = "COMPX_AI_BG_REMOVED|1|TOKEN=" + String(token || "") + "|SOURCE_ID=" + String(original.id) + "|ORIGINAL_ENABLED=" + (originalWasEnabled ? "1" : "0") + "|FOOTAGE_ID=" + String(imported.id) + "|DROPPED=1";
    if (disableOriginal !== false) original.enabled = false;
    original.selected = false;
    result.selected = true;
    app.endUndoGroup(); undoOpen = false;
    return toolResult(true, "Background removed from the dropped image and imported into the active composition.");
  } catch (error) {
    if (undoOpen) try { app.endUndoGroup(); } catch (undoError) { compxAuditFallback("HOST_BG_DROP_IMPORT_UNDO_001", undoError); }
    return toolResult(false, "Could not import the dropped image: " + error.toString());
  }
}

function ae_bgRemoveRestore() {
  var undoOpen = false;
  try {
    var comp = getActiveComp();
    if (!comp) return toolResult(false, "Open a composition first.");
    var layers = getSelectedLayers(comp);
    if (layers.length !== 1) return toolResult(false, "Select one generated AI Cutout layer first.");
    var result = layers[0];
    var tag = String(result.comment || "");
    if (tag.indexOf("COMPX_AI_BG_REMOVED|1|") !== 0) return toolResult(false, "The selected layer is not a CompX AI Cutout.");
    var sourceMatch = tag.match(/\|SOURCE_ID=(\d+)/);
    var enabledMatch = tag.match(/\|ORIGINAL_ENABLED=([01])/);
    if (!sourceMatch) return toolResult(false, "The original-layer reference is missing.");
    var sourceId = Number(sourceMatch[1]);
    var original = null;
    for (var index = 1; index <= comp.numLayers; index++) {
      if (comp.layer(index).id === sourceId) { original = comp.layer(index); break; }
    }
    if (!original) return toolResult(false, "The preserved original layer could not be found.");
    app.beginUndoGroup("CompX Restore Background Original"); undoOpen = true;
    original.enabled = !enabledMatch || enabledMatch[1] === "1";
    result.remove();
    original.selected = true;
    app.endUndoGroup(); undoOpen = false;
    return toolResult(true, "Original still-image layer restored.");
  } catch (error) {
    if (undoOpen) try { app.endUndoGroup(); } catch (undoError) { compxAuditFallback("HOST_BG_RESTORE_UNDO_001", undoError); }
    return toolResult(false, "Could not restore the original layer: " + error.toString());
  }
}

