function compxFlexCaption_collectLayers(comps) {
  var layers = [];
  for (var c = 0; c < comps.length; c++) {
    var target = comps[c];
    for (var i = 1; i <= target.numLayers; i++) layers.push(target.layer(i));
  }
  return layers;
}

function compxFlexCaption_hasCaptions(comp) {
  for (var i = 1; i <= comp.numLayers; i++) {
    var parts = String(comp.layer(i).comment || "").split("|");
    if (parts[0] === "COMPX_CAPTION") return true;
  }
  return false;
}

