    stage="creating composition";
    var folder=app.project.items.addFolder(name+" Assets"),show=app.project.items.addComp(name,width,height,1,duration,fps);show.parentFolder=folder;show.comment="COMPX_SHOWCASE|"+template+"|2";show.bgColor=compxShowcaseHex(config.background);show.motionBlur=motionBlur;
