    var background=show.layers.addShape();background.name="CompX Showcase Background";background.comment="COMPX_SHOWCASE_BACKGROUND";
    var bgGroup=background.property("ADBE Root Vectors Group").addProperty("ADBE Vector Group"),bgContents=bgGroup.property("ADBE Vectors Group"),bgRect=bgContents.addProperty("ADBE Vector Shape - Rect");bgRect.property("ADBE Vector Rect Size").setValue([width+4,height+4]);var bgFill=bgContents.addProperty("ADBE Vector Graphic - Fill");background.property("ADBE Transform Group").property("ADBE Position").setValue([width/2,height/2]);
    var controller=show.layers.addNull(duration);controller.name="CompX Showcase Controller";controller.comment="COMPX_SHOWCASE_CONTROLLER|"+template;controller.threeDLayer=true;controller.property("ADBE Transform Group").property("ADBE Position").setValue([width/2,height/2,0]);
    compxShowcaseSlider(controller,"Card Count",sources.length);compxShowcaseSlider(controller,"Loop Duration",duration);compxShowcaseSlider(controller,"Radius %",radius);compxShowcaseSlider(controller,"Card Scale %",cardScale);compxShowcaseSlider(controller,"Vertical Spread %",vertical);compxShowcaseSlider(controller,"Perspective %",perspective);compxShowcaseSlider(controller,"Pulse %",pulse);compxShowcaseSlider(controller,"Spin Direction",1);compxShowcaseColor(controller,"Background Color",compxShowcaseHex(config.background));
