      for(var cleanup=1;cleanup<=sourceComp.numLayers;cleanup++){var temp=sourceComp.layer(cleanup);try{if(temp.source===sourceItem){temp.remove();break;}}catch(eCleanup){compxAuditFallback("HOST_AE_MOTIONSHOWCASE_CLEANUP_001",eCleanup);}}
