      var media=cardComp.layers.add(sourceItem);media.name="MEDIA - "+original.name;var cover=Math.max(cardW/sourceItem.width,cardH/sourceItem.height)*100;media.property("ADBE Transform Group").property("ADBE Scale").setValue([cover,cover]);media.property("ADBE Transform Group").property("ADBE Position").setValue([cardW/2,cardH/2]);try{media.outPoint=60;}catch(eMediaOut){compxAuditFallback("HOST_AE_MOTIONSHOWCASE_MEDIAOUT_001",eMediaOut);}
      try{if(sourceItem.duration>0&&sourceItem.duration<60&&media.canSetTimeRemapEnabled){media.timeRemapEnabled=true;media.property("ADBE Time Remapping").expression='loopOut("cycle")';}}catch(eLoop){compxAuditFallback("HOST_AE_MOTIONSHOWCASE_LOOP_001",eLoop);}
      var matte=cardComp.layers.addShape();matte.name="Rounded Matte";matte.property("ADBE Transform Group").property("ADBE Position").setValue([cardW/2,cardH/2]);var mg=matte.property("ADBE Root Vectors Group").addProperty("ADBE Vector Group"),mc=mg.property("ADBE Vectors Group"),mr=mc.addProperty("ADBE Vector Shape - Rect");mr.property("ADBE Vector Rect Size").setValue([cardW-4,cardH-4]);mr.property("ADBE Vector Rect Roundness").setValue(Math.min(corner,Math.min(cardW,cardH)/2));mc.addProperty("ADBE Vector Graphic - Fill");
      try{media.setTrackMatte(matte,TrackMatteType.ALPHA);}catch(eMatte){try{matte.moveBefore(media);media.trackMatteType=TrackMatteType.ALPHA;}catch(eOldMatte){compxAuditFallback("HOST_AE_MOTIONSHOWCASE_MATTE_001",eOldMatte);}}
      var border=cardComp.layers.addShape();border.name="Card Border";border.property("ADBE Transform Group").property("ADBE Position").setValue([cardW/2,cardH/2]);var borderGroup=border.property("ADBE Root Vectors Group").addProperty("ADBE Vector Group"),borderContents=borderGroup.property("ADBE Vectors Group"),borderRect=borderContents.addProperty("ADBE Vector Shape - Rect");borderRect.property("ADBE Vector Rect Size").setValue([cardW-3,cardH-3]);borderRect.property("ADBE Vector Rect Roundness").setValue(Math.min(corner,Math.min(cardW,cardH)/2));var stroke=borderContents.addProperty("ADBE Vector Graphic - Stroke");stroke.property("ADBE Vector Stroke Color").setValue([.75,.75,.75]);stroke.property("ADBE Vector Stroke Opacity").setValue(22);stroke.property("ADBE Vector Stroke Width").setValue(2);border.moveToBeginning();
      var card=show.layers.add(cardComp);card.name="CompX Card "+(s+1)+" - "+original.name;card.comment="COMPX_SHOWCASE_CARD|"+s;card.threeDLayer=true;card.motionBlur=motionBlur;card.parent=controller;
      var position=card.property("ADBE Transform Group").property("ADBE Position"),common='c=thisComp.layer("CompX Showcase Controller");n=Math.max(c.effect("Card Count")("Slider"),1);r=Math.min(thisComp.width,thisComp.height)*c.effect("Radius %")("Slider")/100;v=Math.min(thisComp.width,thisComp.height)*c.effect("Vertical Spread %")("Slider")/100;i='+s+';';
      if(template==="helix")position.expression=common+'a=(i/n)*Math.PI*4;den=Math.max(n-1,1);[Math.sin(a)*r*.78,(i/den-.5)*v*4,Math.cos(a)*r*.78]';else if(template==="depth")position.expression=common+'d=Math.max(c.effect("Loop Duration")("Slider"),.1);dir=c.effect("Spin Direction")("Slider");ph=((i/n)+(time/d)*dir)%1;[Math.sin(ph*Math.PI*2)*v*.42,Math.cos(ph*Math.PI*2)*v*.24,(ph-.5)*r*2]';else position.expression=common+'a=(i/n)*Math.PI*2;[Math.sin(a)*r,Math.sin(a*2)*v,Math.cos(a)*r]';
      card.property("ADBE Transform Group").property("ADBE Scale").expression='c=thisComp.layer("CompX Showcase Controller");n=Math.max(c.effect("Card Count")("Slider"),1);d=Math.max(c.effect("Loop Duration")("Slider"),.1);base=c.effect("Card Scale %")("Slider");pulse=c.effect("Pulse %")("Slider");s=base+pulse*Math.sin((time/d)*Math.PI*2+('+s+'/n)*Math.PI*2);[s,s,s]';
      if(faceCamera)card.autoOrient=AutoOrientType.CAMERA_OR_POINT_OF_INTEREST;else if(template!=="depth")card.property("ADBE Transform Group").property("ADBE Orientation").setValue([0,(s/sources.length)*360+180,0]);
