  compx3drigAddSlider(layer, "Light 1 Angle", 0);
  compx3drigAddSlider(layer, "Light 1 Height", 0);
  compx3drigAddSlider(layer, "Light 1 Distance", 0);
  compx3drigAddSlider(layer, "Light 1 Intensity", 100);
  compx3drigAddColor(layer, "Light 1 Color", [1, 1, 1]);
  compx3drigAddSlider(layer, "Light 2 Angle", 120);
  compx3drigAddSlider(layer, "Light 2 Height", 0);
  compx3drigAddSlider(layer, "Light 2 Distance", 0);
  compx3drigAddSlider(layer, "Light 2 Intensity", 100);
